import Foundation

func correctHomophones(in passage: String) -> String {
    let tokenizedPassage = passage.components(separatedBy: .whitespacesAndNewlines)
    var correctedPassage = ""

    for token in tokenizedPassage {
        guard !token.isEmpty else { continue }

        if let homophone = findHomophone(for: token) {
            correctedPassage += "\(homophone)\(" ".appending(if: token == "the"))"
        } else {
            correctedPassage += token + " "
        }
    }

    return correctedPassage.trimmingCharacters(in: .whitespacesAndNewlines)
}

