Here's an example of a React component using hooks to convert between different temperature units:

```javascript
import React, { useState } from 'react';

const TemperatureConverter = () => {
  const [temperature, setTemperature] = useState(0);
  const [unit, setUnit] = useState('celsius');

  const handleConvert = (e) => {
    e.preventDefault();

    if (unit === 'celsius') {
      const fahrenheit = (temperature * 9 / 5) + 32;
      setTemperature(fahrenheit);
      setUnit('fahrenheit');
    } else {
      const celsius = (temperature - 32) * 5 / 9;
      setTemperature(celsius);
      setUnit('celsius');
    }
  };

  return (
    <div>
      <form onSubmit={handleConvert}>
        <label htmlFor="temperature">Enter the temperature:</label>
        <input type="number" id="temperature" value={temperature} onChange={(e) => setTemperature(parseFloat(e.target.value))} />
        <button type="submit">Convert</button>
      </form>
      <p>Result: {temperature} {unit}</p>
    </div>
  );
};

export default TemperatureConverter;
```

Creating a dynamic webpage with a changing sun appearance based on time is an interesting project! You can achieve this by combining PHP, CSS, and JavaScript. Here's a simple approach to get you started:

1. Create a PHP script (e.g., `sun_appearance.php`) that generates a CSS file based on the current time.
2. Use CSS to style the sun image based on the time of day.
3. Use JavaScript to load the generated CSS file and update the sun image accordingly.

Here's some sample code to help you get started:

`sun_appearance.php`:
```php
<?php
// Get the current time
$current_time = time();

// Calculate the hour (0-23)
$hour = date('H', $current_time);

// Define the CSS rules for each hour range
$css_rules = [
    'day' => [
        'background-color' => 'yellow',
        'border-radius' => '50%',
        'width' => '100px',
        'height' => '100px',
    ],
    'sunset' => [
        'background-color' => 'red',
        'border-radius' => '50%',
        'width' => '100px',
        'height' => '100px',
    ],
    'night' => [
        'background-color' => 'blue',
        'border-radius' => '50%',
        'width' => '100px',
        'height' => '100px',
    ],
];

// Generate the CSS file
$css = '';
foreach ($css_rules as $range => $styles) {
    if ($hour >= $range && $hour < $range + 1) {
        $css .= ".$range {\n";
        foreach ($styles as $property => $value) {
            $css .= "    $property: $value;\n";
        }
        $css .= "}\n";
    }
}

// Output the CSS file
header('Content-Type: text/css');
echo $css;
?>
```
