					}
					err = ioutil.WriteFile("struct.avsc", []byte(schema), 0644)
					if err != nil {
						fmt.Println("Error writing schema file:", err)
						return
					}
					fmt.Printf("Avro schema generated for %s\n", structName)
					return
				}
			}
		}
	}

	fmt.Println("Struct not found in file.")
}

