```json
{
  "hotels": [
    {
      "_id": ObjectId("63123456789abcdef"),
      "name": "Hotel X",
      "rooms": [
        {
          "_id": ObjectId("63123456789abcdef_room_1"),
          "number": 1,
          "type": "Standard",
          "price": 100,
          "occupancy": 0,
          "reservations": []
        },
        // ... (up to 1K rooms)
      ]
