Now, let's create a simple script to identify the most common non-silent vowel and consonant combinations in a given text:

```python
import nltk
from nltk.corpus import wordnet
from nltk.tokenize import word_tokenize
from nltk.stem import WordNetLemmatizer

def get_vowels():
    vowels = set()
    for synset in wordnet.synsets('v'):
        for lemma in synset.lemmas():
            vowels.add(lemma.name().lower())
    return vowels

def get_consonants():
    consonants = set()
    for synset in wordnet.synsets('conjunction'):
        for lemma in synset.lemmas():
            consonants.add(lemma.name().lower())
    return consonants

def count_combinations(text):
    vowels = get_vowels()
    consonants = get_consonants()
    combos = {}

    tokens = word_tokenize(text)
    lemmatizer = WordNetLemmatizer()
    tokens = [lemmatizer.lemmatize(token) for token in tokens]

    for i in range(len(tokens)):
        for j in range(i+1, len(tokens)):
            combo = f"{tokens[i]} {tokens[j]}"
            if combo not in combos:
                combos[combo] = 0
            combos[combo] += 1

    return combos

def find_most_common(combos):
    max_count = 0
    result = None

    for combo, count in combos.items():
        if count > max_count:
            max_count = count
            result = combo

    return result

