Here's a simple decorator that checks the `NODE_ENV` variable and calls the next middleware or returns `false` depending on its value:

```typescript
import { ExecutionContext, Injectable, CanActivate } from '@nestjs/common';

@Injectable()
export class EnvironmentMiddleware implements CanActivate {
  canActivate(context: ExecutionContext): boolean | Promise<boolean> {
    const env = context.switchToHttp().getRequest().env;

    return env.NODE_ENV === 'true';
  }
}
```

You can use this decorator in your controller or route like this:

```typescript
import { Controller, Get } from '@nestjs/common';
import { EnvironmentMiddleware } from './environment.middleware';

@Controller('your-controller-path')
export class YourController {
  constructor(private readonly environmentMiddleware: EnvironmentMiddleware) {}

  @Get()
  async getData() {
    await this.environmentMiddleware.canActivate(this); // Will return true if NODE_ENV is set to true

    // Your business logic here
  }
}
```

