    <ul>
        <li>3</li>
        <li>7</li>
        <li>13</li>
        <li>19</li>
    </ul>
    <script>
        // Function to calculate the product of the prime numbers
        function calculateProduct() {
            const primeNumbers = [3, 7, 13, 19];
            let product = 1;

            for (const number of primeNumbers) {
                product *= number;
            }

            return product;
        }

        // Display the product of the prime numbers
        document.write(`The product of the prime numbers is ${calculateProduct()}.`);
    </script>
</body>
</html>
```

