function generateBarChart(dataset: Array<{ x: string, y: number }>) {
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d');

  canvas.width = 800;
  canvas.height = 400;

  const bars = dataset.map((item) => ({
    x: item.x,
    y: item.y,
    width: 10,
    height: item.y
  }));

  bars.sort((a, b) => a.x - b.x);

  ctx.fillStyle = 'blue';

  bars.forEach((bar) => {
    ctx.fillRect(bar.x, bar.y, bar.width, bar.height);
  });

  return canvas;
}

const dataset = [
  { x: 'Apple', y: 5 },
  { x: 'Banana', y: 3 },
  { x: 'Orange', y: 2 },
];

const chart = generateBarChart(dataset);
document.body.appendChild(chart);
