Here's a simple React utility to remove widows:

```javascript
import React, { useState } from 'react';

const RemoveWidows = ({ text }) => {
  const [widowsRemoved, setWidowsRemoved] = useState(false);

  const handleRemoveWidows = () => {
    setWidowsRemoved(true);
  };

  return (
    <div>
      <button onClick={handleRemoveWidows}>Remove Widows</button>
      {widowsRemoved && (
        <div>
          <p>Original text:</p>
          <pre>{text}</pre>
          <p>Removed widows:</p>
          <pre>{text.split('\n').map((line) => line.trim()).join('\n')}</pre>
        </div>
      )}
    </div>
  );
};

export default RemoveWidows;
```

To use this component, simply pass in the text you want to remove widows from:

```javascript
import React from 'react';
import RemoveWidows from './RemoveWidows';

const App = () => {
  return (
    <div>
      <RemoveWidows text="Lorem ipsum dolor sit amet, consectetur adipiscing elit." />
    </div>
  );
};

export default App;
```

