To find the kth largest element in the given list, we can use the quickselect algorithm. Here's a Python implementation of the quickselect algorithm:

```python
def quick_select(numbers, k):
    def partition(left, right):
        pivot = numbers[right]
        i = left - 1
        for j in range(left, right):
            if numbers[j] <= pivot:
                i += 1
                numbers[i], numbers[j] = numbers[j], numbers[i]
        numbers[i + 1], numbers[right] = numbers[right], numbers[i + 1]
        return i + 1

    def quick_select_helper(left, right, k):
        if left == right:
            return numbers[left]
        pivot_index = partition(left, right)
        if pivot_index == k - 1:
            return numbers[pivot_index]
        elif pivot_index > k - 1:
            return quick_select_helper(left, pivot_index - 1, k)
        else:
            return quick_select_helper(pivot_index + 1, right, k)

    return quick_select_helper(0, len(numbers) - 1, k)

