def find_longest_word(s):
    max_length = 0
    longest_word = ""
    current_word = ""

    for char in s:
        if char == ' ':
            if len(current_word) > max_length:
                max_length = len(current_word)
                longest_word = current_word
            current_word = ""
        else:
            current_word += char

    if current_word != "":
        if len(current_word) > max_length:
            max_length = len(current_word)
            longest_word = current_word

    return longest_word

