Now, create a script to recursively check folders for SIDHistory references:

```powershell
# Import ActiveDirectory module
Import-Module ActiveDirectory

# Function to check if a SID is present in the SIDHistory of any user or group in the domain
function CheckSIDHistory($sid) {
    $domain = (Get-ADDomain).Name
    $users = Get-ADUser -Filter {(SIDHistory -like "*$sid*")} -Properties SIDHistory -SearchBase "DC=$domain,DC=com"
    $groups = Get-ADGroup -Filter {(SIDHistory -like "*$sid*")} -Properties SIDHistory -SearchBase "DC=$domain,DC=com"

    if ($users -or $groups) {
        return $true
    } else {
        return $false
    }
}

# Function to recursively check folders for SIDHistory references
function CheckFolderACLs($folderPath) {
    $acl = Get-Acl -Path $folderPath
    $recursive = $true

    while ($recursive) {
        foreach ($access in $acl.Access) {
            if ($access.IdentityReference -match '^S-1-5-21-') {
                $sid = $access.IdentityReference
                if (CheckSIDHistory($sid)) {
                    Write-Host "Folder '$folderPath' has an ACL reference to a SID from the SIDHistory of a user or group in the domain."
                }
            }
        }

        $recursive = $acl.IsContainer
        if ($recursive) {
            foreach ($subFolder in $acl.GetReferencedObjects()) {
                CheckFolderACLs($subFolder.FullName)
            }
        }
    }
}

# Example usage
$folderPath = "C:\Your_Folder_Path"
CheckFolderACLs
